#!/usr/bin/env python3
# Exact rational verifier for lemma L1, finite scope.
# Discipline: no imports, no print, no open, no filesystem, no network,
# deterministic, exact integer arithmetic only, fail closed.
# Entrypoint: verify(witness) — raises on any failed check; returns on PASS.

def subset_sums(A):
    sums = [0]
    for a in A:
        sums = sums + [s + a for s in sums]
    return sums

def cross_mult_distinct(A):
    # Each integer sum s is represented as the exact rational (s, 1).
    # (a, b) != (c, d) for b, d > 0 iff a*d != c*b (cross-multiplied,
    # exact integer comparison). Any non-positive denominator is an
    # unresolved sign: return None -> abort.
    fracs = [(s, 1) for s in subset_sums(A)]
    n = len(fracs)
    for i in range(n):
        for j in range(i + 1, n):
            a, b = fracs[i]
            c, d = fracs[j]
            if b <= 0 or d <= 0:
                return None
            if a * d == c * b:
                return False
    return True

def check_instance(inst):
    # returns 'DISTINCT', 'NOT_DISTINCT', or 'ABORT'; raises on anomaly
    N = inst['N']
    A = inst['A']
    if type(N) is not int:
        raise ValueError('N not int')
    if N <= 0:
        if inst['expected'] != 'ABORT':
            raise ValueError('out-of-scope N not marked ABORT')
        return 'ABORT'
    if type(A) is not list or len(A) == 0:
        raise ValueError('A malformed')
    for x in A:
        if type(x) is not int or x < 1 or x > N:
            raise ValueError('element outside [1, N]')
    if len(set(A)) != len(A):
        raise ValueError('duplicate elements')
    d = cross_mult_distinct(A)
    if d is None:
        if inst['expected'] != 'ABORT':
            raise ValueError('unresolved sign not marked ABORT')
        return 'ABORT'
    if d is True:
        if inst['expected'] != 'DISTINCT':
            raise ValueError('distinctness mismatch')
        return 'DISTINCT'
    if inst['expected'] != 'NOT_DISTINCT':
        raise ValueError('collision mismatch')
    return 'NOT_DISTINCT'

def verify(witness):
    results = []
    for key in ('positive_instance', 'negative_control', 'abort_control'):
        results.append(check_instance(witness[key]))
    if results != ['DISTINCT', 'NOT_DISTINCT', 'ABORT']:
        raise ValueError('instance verdicts do not match required pattern')
    return results

WITNESS = {
    'positive_instance': {'N': 10, 'A': [2, 3, 7], 'expected': 'DISTINCT'},
    'negative_control': {'N': 10, 'A': [2, 3, 5], 'expected': 'NOT_DISTINCT'},
    'abort_control': {'N': 0, 'A': [], 'expected': 'ABORT'}
}

verify(WITNESS)
